'use strict';
(function(){
  const read=async file=>{if(file.size>2*1024*1024)throw Error(file.name+': maximum file size is 2 MB');const b=new Uint8Array(await file.arrayBuffer());let type='';if(b[0]===137&&b[1]===80&&b[2]===78&&b[3]===71)type='image/png';else if(b[0]===255&&b[1]===216&&b[2]===255)type='image/jpeg';else if(String.fromCharCode(...b.slice(0,4))==='RIFF'&&String.fromCharCode(...b.slice(8,12))==='WEBP')type='image/webp';else if(String.fromCharCode(...b.slice(0,5))==='%PDF-')type='application/pdf';if(!type)throw Error(file.name+': only PDF, JPG, PNG and WebP files are supported');const data=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(Error('Unable to read '+file.name));r.readAsDataURL(new Blob([b],{type}))});return {name:file.name,size:file.size,type,data,uploadedAt:new Date().toISOString()}};
  document.addEventListener('change',async event=>{const input=event.target.closest?.('[data-identity-upload]');if(!input)return;event.preventDefault();event.stopImmediatePropagation();const file=input.files?.[0];if(!file)return;input.disabled=true;try{const saved=await read(file),name=input.dataset.identityUpload,hidden=$('#'+name+'Value'),current=$('#'+name+'Current');hidden.value=JSON.stringify(saved);current.innerHTML=`<span>${esc(saved.name)} · ${Math.ceil(saved.size/1024)} KB</span> <a class="btn secondary small" href="${esc(saved.data)}" target="_blank" rel="noopener">View</a> <a class="btn secondary small" href="${esc(saved.data)}" download="${esc(saved.name)}">Download</a> <button type="button" class="btn danger small" data-remove-identity="${name}">Remove</button>`}catch(error){toast(error.message)}finally{input.disabled=false;input.value=''}},true);
  new MutationObserver(()=>document.querySelectorAll('.staffIdentityFile .field small').forEach(el=>{if(el.textContent.includes('up to 1 MB'))el.textContent=el.textContent.replace('up to 1 MB','up to 2 MB')})).observe(document.body,{childList:true,subtree:true});
})();
